So I would assume something like this would work:
```c

#define MODEM_NODE    DT_ALIAS(modem)

static struct modem_pipelink *gnss_pipelink = MODEM_PIPELINK_DT_GET(MODEM_NODE, gnss_pipe);

static void open_pipe_work_handler(struct k_work *work);
static void init_gnss_work_handler(struct k_work *work);
static void parse_gnss_data_work_handler(struct k_work *work);
static void pipe_callback(struct modem_pipe *pipe, enum modem_pipe_event event, void *user_data);
static K_WORK_DEFINE(open_pipe_work, open_pipe_work_handler);
static K_WORK_DEFINE(init_gnss_work, init_gnss_work_handler);
static K_WORK_DEFINE(parse_gnss_data_work, parse_gnss_data_work_handler);

/* Get notify when the GNSS pipe is connected or disconnected */
void gnss_pipelink_callback(struct modem_pipelink *link, enum modem_pipelink_event event,
			    void *user_data)
{
	ARG_UNUSED(user_data);

	switch (event) {
	case MODEM_PIPELINK_EVENT_CONNECTED:
		LOG_INF("pipe connected");
		k_work_submit(&open_pipe_work);
		break;

	case MODEM_PIPELINK_EVENT_DISCONNECTED:
		LOG_INF("pipe disconnected");
		break;
	default:
		break;
	}
}

/* Register pipelink callback, must be called after modem_cellular_init() */
int gnss_pipe_init(void)
{
	modem_pipelink_attach(gnss_pipelink, gnss_pipelink_callback, NULL);
	return 0;
}
SYS_INIT(gnss_pipe_init, APPLICATION, 0);

/* Open the pipe when modem is active */
static void open_pipe_work_handler(struct k_work *work)
{
	struct modem_pipe *pipe = modem_pipelink_get_pipe(gnss_pipelink);
	modem_pipe_attach(pipe, pipe_callback, NULL);
	modem_pipe_open_async(pipe);
}

/* Pipe callback */
static void pipe_callback(struct modem_pipe *pipe, enum modem_pipe_event event,
			  void *user_data)
{
	static bool pipe_opened;
	ARG_UNUSED(user_data);

	switch (event) {
	case MODEM_PIPE_EVENT_OPENED:
		if (!pipe_opened) {
			pipe_opened = true;
			k_work_submit(&init_gnss_work);
		}
		break;
	case MODEM_PIPE_EVENT_CLOSED:
		if (pipe_opened) {
			pipe_opened = false;
		}
		break;
	case MODEM_PIPE_EVENT_RECEIVE_READY:
		k_work_submit(&parse_gnss_data_work);
		break;
	case MODEM_PIPE_EVENT_TRANSMIT_IDLE:
		break;
	}
}

/** Start GNSS functionality.
 * This request modem to wake up which will trigger the GNSS pipe to open.
 */
void gnss_start(void)
{
	pm_device_runtime_get(DEVICE_DT_GET(MODEM_NODE));
}

/** Close our GNSS pipe and release the modem.
 * If PPP is not used, this will put the modem to sleep.
 */
void gnss_stop(void)
{
	struct modem_pipe *pipe = modem_pipelink_get_pipe(gnss_pipelink);
	modem_pipe_close_async(pipe);
	pm_device_runtime_put_async(DEVICE_DT_GET(MODEM_NODE));
}

